SELECT
FROM raffle_activity_sku
ORDER BY update_time DESC, id DESC LIMIT #{pageSize} OFFSET #{offset}

mapper.update:
UPDATE raffle_activity_sku
SET activity_id = #{definition.activityId},
activity_count_id = #{definition.activityCountId},
credit_amount = #{definition.creditAmount},
version = version + 1,
updated_by = #{definition.updatedBy},
update_time = CURRENT_TIMESTAMP
WHERE sku = #{definition.sku}
AND version = #{definition.version}
AND (
(
activity_id = #{definition.activityId}
AND activity_count_id = #{definition.activityCountId}
)
OR stock_count = stock_count_surplus
)

UPDATE raffle_activity_sku
SET stock_count = stock_count + #{adjustment.quantityDelta},
stock_count_surplus = stock_count_surplus + #{adjustment.quantityDelta},
version = version + 1,
updated_by = #{adjustment.operator},
update_time = CURRENT_TIMESTAMP
WHERE sku = #{adjustment.sku}
AND version = #{adjustment.expectedVersion}
AND stock_count = #{adjustment.stockCountBefore}
AND stock_count_surplus = #{adjustment.stockCountSurplusBefore}
AND stock_count + #{adjustment.quantityDelta} = #{adjustment.stockCountAfter}
AND stock_count_surplus + #{adjustment.quantityDelta} = #{adjustment.stockCountSurplusAfter}
AND stock_count + #{adjustment.quantityDelta} > 0
AND stock_count_surplus + #{adjustment.quantityDelta} >= 0

UPDATE raffle_activity_sku
SET stock_count_surplus = stock_count_surplus - 1,
updated_by = 'system_stock_sync',
update_time = CURRENT_TIMESTAMP
WHERE sku = #{sku}
AND activity_id = #{activityId}
AND activity_count_id = #{activityCountId}
AND stock_count_surplus > 0
